import statistics

def find_zscore_outliers(prices, z_threshold):
    if not prices:
        return []
    mean = statistics.fmean(prices)
    sd = statistics.pstdev(prices)
    result = []
    for i, p in enumerate(prices):
        z = (p - mean) / sd
        if abs(z) > z_threshold:
            result.append((i, p, z))
    return result

