import math

def feature_correlation_matrix(samples):
    if not samples:
        return []
    cols = list(zip(*samples))
    n = len(samples)
    means = [sum(c) / n for c in cols]
    devs = [[x - m for x in c] for c, m in zip(cols, means)]
    norms = [math.sqrt(sum(d * d for d in dv)) for dv in devs]
    k = len(cols)
    result = [[0.0] * k for _ in range(k)]
    for i in range(k):
        for j in range(i, k):
            if i == j:
                r = 1.0
            else:
                r = sum(a * b for a, b in zip(devs[i], devs[j])) / (norms[i] * norms[j])
            result[i][j] = r
            result[j][i] = r
    return result

