from collections import Counter


def bracket_free_tfidf(texts):
    counts = []
    for t in texts:
        cleaned = re.sub(r'\[.*?\]', '', t).lower()
        counts.append(Counter(re.findall(r'\b\w\w+\b', cleaned)))
    n = len(texts)
    df = Counter()
    for c in counts:
        df.update(c.keys())
    idf = {w: math.log((1 + n) / (1 + d)) + 1 for w, d in df.items()}
    result = []
    for c in counts:
        weights = {w: cnt * idf[w] for w, cnt in c.items()}
        norm = math.sqrt(sum(x * x for x in weights.values()))
        result.append({w: x / norm for w, x in weights.items()} if norm else {})
    return result

