def fit_linear_regression(rows, targets):
    n = len(rows)
    if n == 0 or n != len(targets):
        raise ValueError("rows and targets must be non-empty and of equal length")
    p = len(rows[0])
    xm = [sum(r[j] for r in rows) / n for j in range(p)]
    ym = sum(targets) / n
    X = [[r[j] - xm[j] for j in range(p)] for r in rows]
    y = [t - ym for t in targets]
    # normal equations on centered data
    A = [[sum(X[k][i] * X[k][j] for k in range(n)) for j in range(p)] + [sum(X[k][i] * y[k] for k in range(n))] for i in range(p)]
    for col in range(p):
        piv = max(range(col, p), key=lambda r: abs(A[r][col]))
        A[col], A[piv] = A[piv], A[col]
        pv = A[col][col]
        for r in range(p):
            if r != col and A[r][col] != 0:
                f = A[r][col] / pv
                for c in range(col, p + 1):
                    A[r][c] -= f * A[col][c]
    coefs = [A[i][p] / A[i][i] for i in range(p)]
    intercept = ym - sum(c * m for c, m in zip(coefs, xm))
    return (coefs, float(intercept))

